<?php if($allowed['finance']): ?><div class="panel movements-panel" data-reveal><div class="panel-heading"><div><span class="eyebrow">CAJA Y CUENTAS POR COBRAR</span><h2>Movimientos financieros</h2><p>Cada concepto conserva su naturaleza: cobros, anulaciones, saldos o procedimientos valorizados.</p></div><?php if(can('payments')): ?><a class="button secondary small" href="<?= e(url('/admin/payments')) ?>">Abrir caja <?= icon('arrow',15) ?></a><?php endif; ?></div><div class="finance-summary"><div><span>Ingresos vigentes</span><strong><?= money($totals['income']) ?></strong><small><?= (int)$totals['payments'] ?> pagos / abonos en el período</small></div><div><span>Anulaciones del período</span><strong><?= money($totals['voided']) ?></strong><small>Operaciones contables conservadas</small></div><div><span>Saldo actual</span><strong><?= money($totals['balance']) ?></strong><small>Planes creados en el período</small></div></div><div class="table-wrap" tabindex="0" role="region" aria-label="Movimientos financieros"><table><thead><tr><th>Tipo / concepto</th><th>Paciente</th><th>Valor</th><th>Estado</th><th>Responsable / fecha</th><th>Detalle</th></tr></thead><tbody><?php foreach($finance['rows'] as $r): ?><tr><td><span class="movement-type <?= e($r['type']) ?>"><?= e(App\Services\Dashboard::type($r['type'])) ?></span><strong><?= e($r['concept']) ?></strong></td><td><?= e($r['patient']) ?></td><td class="movement-amount <?= $r['type']==='void' ? 'negative':'' ?>"><?= money($r['amount']) ?></td><td><span class="badge <?= e($r['status']) ?>"><?= e(App\Services\Dashboard::status($r['status'])) ?></span></td><td><?= e($r['author']) ?><small><?= local_date($r['occurred_at']) ?></small></td><td><button class="icon-button" type="button" data-movement="<?= e($r['row_key']) ?>" aria-label="Ver detalle de <?= e($r['concept']) ?>"><?= icon('arrow',17) ?></button></td></tr><?php endforeach; ?><?php if(!$finance['rows']): ?><tr><td colspan="6" class="empty"><h3>No hay movimientos con estos filtros.</h3><p>Cambia las fechas, el paciente o el tipo. Los cobros reales aparecerán aquí.</p><a class="text-link" data-dashboard-nav href="<?= e(App\Services\Dashboard::link($f,['finance_type'=>'','finance_status'=>'','q'=>'','finance_page'=>1])) ?>">Limpiar filtros de caja <?= icon('arrow',15) ?></a></td></tr><?php endif; ?></tbody></table></div><?php view('dashboard/parts/pagination',['f'=>$f,'feed'=>$finance,'stream'=>'finance']); ?><p class="movement-disclaimer">Los saldos y los valores de procedimientos no son ingresos. Una anulación no procesa devoluciones bancarias.</p></div><?php endif; ?>
